package jp.tapmarker;
import java.util.*;

public final class DailyRouteTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static float[] image(float low,float high){float[] pixels=new float[768];for(int i=0;i<pixels.length;i++)pixels[i]=i%6<3?low:high;return pixels;}
 static DailyCompletion profile(){return new DailyCompletion(new float[]{.2f,.3f,.8f,.4f},new float[]{.2f,.1f,.8f,.15f},image(.1f,.9f),image(.2f,.8f));}
 static void observe(PhaseEngine e,Map<String,float[]> samples,long now){DailyCompletion.continuation(e,samples);e.observe(samples,now);}
 static void order(){DailyRoute r=new DailyRoute();long run=r.start(new String[]{"game.a","game.b","game.a","game.c"});check(r.size()==3&&r.current().equals("game.a"),"selected order is retained, duplicates removed");check(!r.complete("game.b",run)&&r.position()==1,"another app cannot finish the current daily");check(r.complete("game.a",run)&&r.current().equals("game.b"),"verified A advances to B");check(!r.complete("game.a",run)&&r.position()==2,"late duplicate completion never skips B");check(r.complete("game.b",run)&&r.current().equals("game.c"),"B advances to C");check(r.complete("game.c",run)&&!r.active()&&r.current().isEmpty(),"last app stops and does not loop back");check(!r.complete("game.c",run),"completion after final stop is ignored");run=r.start(new String[]{"game.a","game.b"});r.stop();check(!r.complete("game.a",run),"all-stop invalidates queued completion");long next=r.start(new String[]{"game.a","game.b"});check(!r.complete("game.a",run)&&r.current().equals("game.a"),"previous run cannot advance a new run");check(r.complete("game.a",next),"new run remains usable");}
 static PhaseEngine engine(){PhaseEngine e=new PhaseEngine();PhaseEngine.Phase main=new PhaseEngine.Phase();main.id="main";main.name="game";main.markersDuring=true;e.phases.put(main.id,main);e.initial=e.current=main.id;return e;}
 static void evidence(){
  PhaseEngine saved=engine(),e=saved.runtimeCopy();e.strictRuntime=true;profile().install(e);e.enter("main",0);check(!saved.regions.containsKey(DailyCompletion.REGION),"daily mode never overwrites saved game definitions");check(e.validate().isEmpty(),"completion watch and guard form a valid graph");
  Map<String,float[]> samples=new HashMap<>();samples.put(DailyCompletion.REGION,image(.1f,.9f));observe(e,samples,100);observe(e,samples,10000);check(e.poll()==null,"missing heading and elapsed time cannot finish daily");samples.put(DailyCompletion.HEADING,image(.2f,.8f));samples.put(DailyCompletion.REGION,image(.4f,.6f));observe(e,samples,11000);observe(e,samples,11200);check(e.poll()==null,"unfinished evidence keeps current app");samples.put(DailyCompletion.REGION,image(.1f,.9f));observe(e,samples,12000);check(e.poll()==null,"first matching image holds");samples.put(DailyCompletion.HEADING,image(.4f,.6f));observe(e,samples,12120);check(e.poll()==null,"a changed heading resets completion confirmation");samples.put(DailyCompletion.HEADING,image(.2f,.8f));observe(e,samples,12240);check(e.poll()==null,"matching again still requires a second fresh observation");observe(e,samples,12360);PhaseEngine.Watch done=e.poll();check(done!=null&&done.action==PhaseEngine.WAIT&&done.nextPhase.equals(DailyCompletion.PHASE),"two independent landmarks matching twice produce completion without an extra tap");e.finish(done,12360);check(e.current.equals(DailyCompletion.PHASE)&&e.lastCompletedRule.startsWith(DailyCompletion.RULE+":"),"terminal transition has actual completion-rule evidence");
  boolean rejected=false;try{new DailyCompletion(new float[]{.2f,.3f,.8f,.4f},new float[]{.2f,.1f,.8f,.15f},new float[768],new float[768]);}catch(IllegalArgumentException invalid){rejected=true;}check(rejected,"blank image cannot be registered as complete");rejected=false;try{new DailyCompletion(new float[]{.2f,.3f,.8f,.4f},new float[]{.2f,.3f,.8f,.4f},image(.1f,.9f),image(.2f,.8f));}catch(IllegalArgumentException invalid){rejected=true;}check(rejected,"same pixels cannot masquerade as two independent landmarks");
 }
 static void nextPlay(){
  PhaseEngine e=engine();e.strictRuntime=true;PhaseEngine.Region play=new PhaseEngine.Region();play.id="play";play.name="Play";play.bounds=new float[]{.2f,.8f,.8f,.9f};e.regions.put(play.id,play);PhaseEngine.Phase next=new PhaseEngine.Phase();next.id="next-stage";next.name="next stage";e.phases.put(next.id,next);
  PhaseEngine.Watch button=new PhaseEngine.Watch();button.id="play-next";button.regionId="play";button.condition=PhaseEngine.MATCH;button.reference=image(.3f,.7f);button.nextPhase=next.id;e.phases.get("main").watches.add(button);PhaseEngine.Watch retry=new PhaseEngine.Watch();retry.id="retry";retry.condition=PhaseEngine.TIMEOUT;retry.timeoutMs=50;retry.action=PhaseEngine.WAIT;retry.nextPhase=next.id;e.phases.get("main").watches.add(retry);profile().install(e);e.enter("main",0);check(e.validate().isEmpty(),"daily completion preserves a valid graph when next-play and timer rules exist");
  Map<String,float[]> samples=new HashMap<>();samples.put("play",image(.3f,.7f));samples.put(DailyCompletion.REGION,image(.1f,.9f));samples.put(DailyCompletion.HEADING,image(.2f,.8f));observe(e,samples,100);check(e.poll()==null,"first complete observation holds Play and elapsed retry");observe(e,samples,220);PhaseEngine.Watch done=e.poll();check(done!=null&&done.id.startsWith(DailyCompletion.RULE+":"),"completion advances instead of starting another stage or an ambiguous branch");
  e.enter("main",300);samples.put(DailyCompletion.REGION,image(.4f,.6f));observe(e,samples,300);check(e.poll()==null,"unfinished Play requires confirmation");observe(e,samples,320);check(e.poll()==button,"ordinary Play remains available while daily is unfinished");
 }
 public static void main(String[] args){order();evidence();nextPlay();System.out.println("DailyRouteTest: "+checks+" checks passed; finite order, cancellation and explicit visual completion logic; real all-daily-done game screens not provided");}
}
